"""Migrated Meridian CRM 4.2 order validation rules."""

from decimal import Decimal
from typing import Any


def _field(row: dict | None, column: str) -> Any:
    """Return a field value, treating missing or null values as empty strings."""
    if row is None:
        return ""
    value = row.get(column, "")
    return "" if value is None else value


def _number(value: Any) -> Decimal:
    """Apply legacy numeric coercion; an empty value compares as zero."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    """Perform a legacy LOOKUP, preserving input row order."""
    if tables is None:
        return ""

    rows = tables.get(table_name, [])
    if rows is None:
        return ""

    for row in rows:
        if _field(row, "DEL_FLG") == "Y":
            continue
        if _field(row, key_column) == key_value:
            return _field(row, output_column)

    return ""


def _failure(code: str, message: str) -> dict:
    return {
        "code": code,
        "message": message,
        "severity": "BLOCK",
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Run applicable migrated rules in legacy rule-file order."""
    errors: list[dict] = []

    if table == "ORD_HEADER":
        # ORD-001
        if event in ("INSERT", "UPDATE"):
            discount = _number(_field(record, "DISC_PCT"))
            if not (discount >= Decimal("0") and discount <= Decimal("100")):
                errors.append(
                    _failure("E5001", "Discount out of range")
                )

        # ORD-002
        if event == "UPDATE":
            discount = _number(_field(record, "DISC_PCT"))
            owner_uid = _field(record, "OWNER_UID")
            valid = not (
                discount > Decimal("20")
                and _lookup(
                    tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
                ) != "MGR"
                and _lookup(
                    tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
                ) != "ADMIN"
            )
            if not valid:
                errors.append(
                    _failure(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        # ORD-003
        if event == "UPDATE":
            old_status = _field(old, "STAT_CD")
            new_status = _field(record, "STAT_CD")
            valid = not (
                old_status == "I"
                and new_status != "I"
                and new_status != "X"
            )
            if not valid:
                errors.append(
                    _failure(
                        "E5003",
                        "Invoiced order can only be cancelled",
                    )
                )

    elif table == "ORD_LINE":
        # ORD-004
        if event in ("INSERT", "UPDATE"):
            quantity = _number(_field(record, "QTY"))
            if not quantity > Decimal("0"):
                errors.append(
                    _failure("E5004", "Quantity must be positive")
                )

        # ORD-005
        if event == "INSERT":
            product_id = _field(record, "PROD_ID")
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                product_id,
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append(
                    _failure("E5005", "Product not active")
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
